-- Phase 18: workforce management. custom_staff_members remains the canonical employee.
create extension if not exists btree_gist with schema extensions;

alter table public.plans add column if not exists workforce_management_enabled boolean not null default true;
alter table public.plans add column if not exists time_clock_enabled boolean not null default true;
alter table public.plans add column if not exists labor_cost_enabled boolean not null default true;
alter table public.plans add column if not exists shift_planning_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists workforce_management_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists time_clock_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists labor_cost_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists shift_planning_enabled boolean not null default true;

alter table public.custom_staff_members add column if not exists organization_id uuid references public.organizations(id) on delete cascade;
alter table public.custom_staff_members add column if not exists employee_code text;
alter table public.custom_staff_members add column if not exists primary_store_id uuid references public.establishments(id) on delete restrict;
alter table public.custom_staff_members add column if not exists hire_date date;
alter table public.custom_staff_members add column if not exists termination_date date;
alter table public.custom_staff_members add column if not exists hourly_cost_cents bigint check(hourly_cost_cents is null or hourly_cost_cents>=0);
alter table public.custom_staff_members add column if not exists monthly_cost_cents bigint check(monthly_cost_cents is null or monthly_cost_cents>=0);
alter table public.custom_staff_members add column if not exists hour_bank_minutes integer not null default 0;
update public.custom_staff_members m set organization_id=e.organization_id,primary_store_id=m.establishment_id from public.establishments e where e.id=m.establishment_id and (m.organization_id is null or m.primary_store_id is null);
create unique index if not exists custom_staff_employee_code_uq on public.custom_staff_members(organization_id,employee_code) where employee_code is not null;
create index if not exists custom_staff_org_store_idx on public.custom_staff_members(organization_id,primary_store_id,status);

create or replace view public.job_roles with (security_invoker=true) as select id,establishment_id,name,description,color,system_key,financial_role,created_at,updated_at from public.staff_roles;
grant select on public.job_roles to authenticated;

create table public.workforce_settings(
 organization_id uuid primary key references public.organizations(id) on delete cascade,
 lateness_tolerance_minutes integer not null default 10 check(lateness_tolerance_minutes between 0 and 180),
 early_leave_tolerance_minutes integer not null default 10 check(early_leave_tolerance_minutes between 0 and 180),
 swap_requires_approval boolean not null default true, overtime_requires_approval boolean not null default true,
 hour_bank_enabled boolean not null default false, enforce_station_shift boolean not null default false,
 authorized_device_required boolean not null default false, updated_at timestamptz not null default now()
);
create table public.workforce_member_permissions(
 organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,
 can_view_team boolean not null default false,can_create_shift boolean not null default false,can_edit_shift boolean not null default false,
 can_publish_shift boolean not null default false,can_view_time_clock boolean not null default false,can_correct_time_clock boolean not null default false,
 can_approve_swap boolean not null default false,can_view_costs boolean not null default false,can_view_productivity boolean not null default false,
 can_manage_skills boolean not null default false,can_view_reports boolean not null default false,updated_at timestamptz not null default now(),
 primary key(organization_id,user_id)
);
create table public.employee_store_assignments(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 employee_id uuid not null references public.custom_staff_members(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 starts_on date not null default current_date,ends_on date,temporary boolean not null default false,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),
 unique(employee_id,store_id,starts_on),check(ends_on is null or ends_on>=starts_on)
);
create table public.employee_availability(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 employee_id uuid not null references public.custom_staff_members(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,
 available_on date not null,start_time time,end_time time,availability text not null check(availability in('available','unavailable','preferred')),
 notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(start_time is null or end_time is null or end_time>start_time)
);
create table public.work_shift_templates(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 employee_id uuid not null references public.custom_staff_members(id) on delete cascade,weekdays smallint[] not null,start_time time not null,end_time time not null,
 break_minutes integer not null default 0 check(break_minutes between 0 and 360),role_context text,active boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.work_shifts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 employee_id uuid not null references public.custom_staff_members(id) on delete cascade,template_id uuid references public.work_shift_templates(id) on delete set null,
 shift_date date not null,starts_at timestamptz not null,ends_at timestamptz not null,break_minutes integer not null default 0 check(break_minutes between 0 and 360),
 role_context text,status text not null default 'scheduled' check(status in('scheduled','confirmed','in_progress','completed','absent','cancelled')),
 publication_status text not null default 'draft' check(publication_status in('draft','published')),version integer not null default 1,
 created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at)
);
alter table public.work_shifts add constraint work_shifts_no_overlap exclude using gist(employee_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status<>'cancelled');
create table public.schedule_publications(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 period_start date not null,period_end date not null,version integer not null,snapshot jsonb not null,published_by uuid references auth.users(id) on delete set null,published_at timestamptz not null default now(),unique(store_id,period_start,period_end,version)
);
create table public.shift_exchange_requests(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,shift_id uuid not null references public.work_shifts(id) on delete cascade,
 requested_by_employee_id uuid not null references public.custom_staff_members(id),target_employee_id uuid references public.custom_staff_members(id),accepted_by_employee_id uuid references public.custom_staff_members(id),
 reason text,status text not null default 'pending_acceptance' check(status in('pending_acceptance','pending_approval','approved','rejected','cancelled')),
 decided_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.time_clock_entries(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 employee_id uuid not null references public.custom_staff_members(id) on delete cascade,shift_id uuid references public.work_shifts(id) on delete set null,
 entry_type text not null check(entry_type in('clock_in','break_start','break_end','clock_out')),occurred_at timestamptz not null default clock_timestamp(),
 source text not null check(source in('panel','authorized_device','pwa','terminal','supervisor_correction')),device_id text,created_by uuid references auth.users(id) on delete set null,
 metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()
);
create table public.time_clock_correction_requests(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,
 entry_id uuid references public.time_clock_entries(id) on delete set null,requested_type text not null check(requested_type in('clock_in','break_start','break_end','clock_out')),
 requested_at timestamptz not null,reason text not null,previous_value jsonb,new_value jsonb,status text not null default 'pending' check(status in('pending','approved','rejected')),
 requested_by uuid references auth.users(id) on delete set null,decided_by uuid references auth.users(id) on delete set null,decided_at timestamptz,created_at timestamptz not null default now()
);
create table public.workforce_approval_requests(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,
 employee_id uuid references public.custom_staff_members(id) on delete cascade,request_type text not null check(request_type in('shift_swap','clock_correction','overtime','justified_absence','schedule_change','coverage')),
 target_id uuid,payload jsonb not null default '{}'::jsonb,status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),
 requested_by uuid references auth.users(id) on delete set null,decided_by uuid references auth.users(id) on delete set null,decision_reason text,created_at timestamptz not null default now(),decided_at timestamptz
);
create table public.employee_skills(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,skill text not null check(skill in('cashier','kitchen','support','delivery','supervisor')),level smallint not null default 1 check(level between 1 and 5),verified_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(employee_id,skill));
create table public.employee_training_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,title text not null,completed_on date,valid_until date,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.employee_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,storage_path text not null,file_name text not null,mime_type text,size_bytes bigint check(size_bytes between 1 and 10485760),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(employee_id,storage_path));
create table public.employee_feedback(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,feedback text not null check(length(btrim(feedback)) between 3 and 2000),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.employee_evaluations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,quality smallint check(quality between 1 and 5),punctuality smallint check(punctuality between 1 and 5),service smallint check(service between 1 and 5),process_adherence smallint check(process_adherence between 1 and 5),notes text,evaluated_by uuid references auth.users(id) on delete set null,evaluated_at timestamptz not null default now());
create table public.employee_notification_preferences(employee_id uuid primary key references public.custom_staff_members(id) on delete cascade,essential_enabled boolean not null default true,shift_reminders boolean not null default true,swap_updates boolean not null default true,correction_updates boolean not null default true,updated_at timestamptz not null default now());
create table public.workforce_notifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.custom_staff_members(id) on delete cascade,kind text not null,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.workforce_action_previews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,requested_by uuid not null references auth.users(id) on delete cascade,action_type text not null check(action_type in('create_shift','update_shift','request_coverage','approve_swap','correct_time_clock','operational_pause','copy_previous_week')),payload jsonb not null,expires_at timestamptz not null default(now()+interval '10 minutes'),confirmed_at timestamptz,created_at timestamptz not null default now());

create index workforce_shift_scope_idx on public.work_shifts(organization_id,store_id,shift_date,status);
create index workforce_shift_employee_idx on public.work_shifts(employee_id,starts_at desc);
create index workforce_clock_scope_idx on public.time_clock_entries(organization_id,store_id,occurred_at desc);
create index workforce_clock_employee_idx on public.time_clock_entries(employee_id,occurred_at desc);
create index workforce_availability_idx on public.employee_availability(employee_id,available_on);
create index workforce_assignment_idx on public.employee_store_assignments(organization_id,store_id,employee_id);
create index workforce_approval_idx on public.workforce_approval_requests(organization_id,status,created_at desc);

create or replace function private.workforce_can_access(target_org uuid,target_store uuid,requested_permission text default 'view') returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$
 select auth.uid() is not null and (
  exists(select 1 from public.organization_members om where om.organization_id=target_org and om.user_id=auth.uid() and om.active and om.role in('owner','admin','manager','supervisor') and (target_store is null or om.all_stores or exists(select 1 from public.organization_member_store_access a where a.organization_id=target_org and a.user_id=om.user_id and a.establishment_id=target_store)))
  or exists(select 1 from public.establishment_members em join public.establishments e on e.id=em.establishment_id where e.organization_id=target_org and em.user_id=auth.uid() and em.status='active' and em.role::text in('owner','manager') and (target_store is null or target_store=em.establishment_id))
  or exists(select 1 from public.workforce_member_permissions p where p.organization_id=target_org and p.user_id=auth.uid() and case requested_permission when 'view' then p.can_view_team when 'create_shift' then p.can_create_shift when 'edit_shift' then p.can_edit_shift when 'publish' then p.can_publish_shift when 'clock' then p.can_view_time_clock when 'correct_clock' then p.can_correct_time_clock when 'approve_swap' then p.can_approve_swap when 'costs' then p.can_view_costs when 'productivity' then p.can_view_productivity when 'skills' then p.can_manage_skills when 'reports' then p.can_view_reports else false end)
 )
$$;
revoke all on function private.workforce_can_access(uuid,uuid,text) from public,anon;grant execute on function private.workforce_can_access(uuid,uuid,text) to authenticated;
create or replace function private.workforce_employee_self(target_employee uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.custom_staff_members where id=target_employee and user_id=auth.uid() and status='active')$$;
revoke all on function private.workforce_employee_self(uuid) from public,anon;grant execute on function private.workforce_employee_self(uuid) to authenticated;
create or replace function private.workforce_audit(target_org uuid,target_store uuid,target_action text,target_type text,target_id uuid,before_value jsonb default null,after_value jsonb default null) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$begin insert into public.audit_logs(establishment_id,actor_id,action,entity_type,entity_id,metadata) values(target_store,auth.uid(),'workforce.'||target_action,target_type,target_id,jsonb_build_object('organization_id',target_org,'before',before_value,'after',after_value));end$$;
revoke all on function private.workforce_audit(uuid,uuid,text,text,uuid,jsonb,jsonb) from public,anon,authenticated;

do $$declare t text;begin foreach t in array array['workforce_settings','workforce_member_permissions','employee_store_assignments','employee_availability','work_shift_templates','work_shifts','schedule_publications','shift_exchange_requests','time_clock_entries','time_clock_correction_requests','workforce_approval_requests','employee_skills','employee_training_records','employee_documents','employee_feedback','employee_evaluations','employee_notification_preferences','workforce_notifications','workforce_action_previews'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy workforce_settings_read on public.workforce_settings for select to authenticated using(private.workforce_can_access(organization_id,null,'view'));
create policy workforce_permissions_read on public.workforce_member_permissions for select to authenticated using(private.workforce_can_access(organization_id,null,'view'));
create policy workforce_assignments_read on public.employee_store_assignments for select to authenticated using(private.workforce_can_access(organization_id,store_id,'view') or private.workforce_employee_self(employee_id));
create policy workforce_availability_read on public.employee_availability for select to authenticated using(private.workforce_can_access(organization_id,store_id,'view') or private.workforce_employee_self(employee_id));
create policy workforce_templates_read on public.work_shift_templates for select to authenticated using(private.workforce_can_access(organization_id,store_id,'view') or private.workforce_employee_self(employee_id));
create policy workforce_shifts_read on public.work_shifts for select to authenticated using(private.workforce_can_access(organization_id,store_id,'view') or (publication_status='published' and private.workforce_employee_self(employee_id)));
create policy workforce_publications_read on public.schedule_publications for select to authenticated using(private.workforce_can_access(organization_id,store_id,'view'));
create policy workforce_swaps_read on public.shift_exchange_requests for select to authenticated using(private.workforce_can_access(organization_id,null,'view') or private.workforce_employee_self(requested_by_employee_id) or private.workforce_employee_self(target_employee_id));
create policy workforce_clock_read on public.time_clock_entries for select to authenticated using(private.workforce_can_access(organization_id,store_id,'clock') or private.workforce_employee_self(employee_id));
create policy workforce_corrections_read on public.time_clock_correction_requests for select to authenticated using(private.workforce_can_access(organization_id,null,'clock') or private.workforce_employee_self(employee_id));
create policy workforce_approvals_read on public.workforce_approval_requests for select to authenticated using(private.workforce_can_access(organization_id,store_id,'view') or private.workforce_employee_self(employee_id));
create policy workforce_skills_read on public.employee_skills for select to authenticated using(private.workforce_can_access(organization_id,null,'view') or private.workforce_employee_self(employee_id));
create policy workforce_training_read on public.employee_training_records for select to authenticated using(private.workforce_can_access(organization_id,null,'view') or private.workforce_employee_self(employee_id));
create policy workforce_documents_read on public.employee_documents for select to authenticated using(private.workforce_can_access(organization_id,null,'view') or private.workforce_employee_self(employee_id));
create policy workforce_feedback_read on public.employee_feedback for select to authenticated using(private.workforce_can_access(organization_id,null,'view'));
create policy workforce_evaluations_read on public.employee_evaluations for select to authenticated using(private.workforce_can_access(organization_id,null,'view'));
create policy workforce_preferences_read on public.employee_notification_preferences for select to authenticated using(private.workforce_employee_self(employee_id) or exists(select 1 from public.custom_staff_members m where m.id=employee_id and private.workforce_can_access(m.organization_id,m.primary_store_id,'view')));
create policy workforce_notifications_read on public.workforce_notifications for select to authenticated using(private.workforce_employee_self(employee_id) or private.workforce_can_access(organization_id,null,'view'));
create policy workforce_previews_read on public.workforce_action_previews for select to authenticated using(requested_by=auth.uid() and private.workforce_can_access(organization_id,store_id,'view'));
grant select on public.workforce_settings,public.workforce_member_permissions,public.employee_store_assignments,public.employee_availability,public.work_shift_templates,public.work_shifts,public.schedule_publications,public.shift_exchange_requests,public.time_clock_entries,public.time_clock_correction_requests,public.workforce_approval_requests,public.employee_skills,public.employee_training_records,public.employee_documents,public.employee_feedback,public.employee_evaluations,public.employee_notification_preferences,public.workforce_notifications,public.workforce_action_previews to authenticated;
revoke insert,update,delete on public.workforce_settings,public.workforce_member_permissions,public.employee_store_assignments,public.employee_availability,public.work_shift_templates,public.work_shifts,public.schedule_publications,public.shift_exchange_requests,public.time_clock_entries,public.time_clock_correction_requests,public.workforce_approval_requests,public.employee_skills,public.employee_training_records,public.employee_documents,public.employee_feedback,public.employee_evaluations,public.employee_notification_preferences,public.workforce_notifications,public.workforce_action_previews from anon,authenticated;

create or replace function public.workforce_save_shift(requested_establishment_id uuid,requested_shift_id uuid,requested_employee_id uuid,requested_start timestamptz,requested_end timestamptz,requested_break_minutes integer default 0,requested_role_context text default null) returns public.work_shifts language plpgsql security definer set search_path=public,private,pg_temp as $$declare s public.work_shifts;org uuid;before_row jsonb;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.workforce_can_access(org,requested_establishment_id,case when requested_shift_id is null then 'create_shift' else 'edit_shift' end) then raise exception 'Sem permissão para alterar a escala';end if;if not exists(select 1 from public.custom_staff_members m where m.id=requested_employee_id and m.organization_id=org and m.status='active') then raise exception 'Funcionário inválido';end if;if requested_shift_id is not null then select to_jsonb(w) into before_row from public.work_shifts w where id=requested_shift_id and organization_id=org for update;end if;insert into public.work_shifts(id,organization_id,store_id,employee_id,shift_date,starts_at,ends_at,break_minutes,role_context,created_by,updated_by) values(coalesce(requested_shift_id,gen_random_uuid()),org,requested_establishment_id,requested_employee_id,requested_start::date,requested_start,requested_end,greatest(requested_break_minutes,0),nullif(btrim(requested_role_context),''),auth.uid(),auth.uid()) on conflict(id) do update set employee_id=excluded.employee_id,store_id=excluded.store_id,shift_date=excluded.shift_date,starts_at=excluded.starts_at,ends_at=excluded.ends_at,break_minutes=excluded.break_minutes,role_context=excluded.role_context,version=work_shifts.version+1,publication_status='draft',updated_by=auth.uid(),updated_at=now() returning * into s;perform private.workforce_audit(org,requested_establishment_id,case when requested_shift_id is null then 'shift_created' else 'shift_updated' end,'work_shift',s.id,before_row,to_jsonb(s));return s;exception when exclusion_violation then raise exception 'Conflito: o funcionário já possui turno neste horário';end$$;
create or replace function public.workforce_publish_schedule(requested_establishment_id uuid,requested_start date,requested_end date) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;v integer;snap jsonb;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.workforce_can_access(org,requested_establishment_id,'publish') then raise exception 'Sem permissão para publicar escala';end if;select coalesce(max(version),0)+1 into v from public.schedule_publications where store_id=requested_establishment_id and period_start=requested_start and period_end=requested_end;update public.work_shifts set publication_status='published',version=v,updated_by=auth.uid(),updated_at=now() where store_id=requested_establishment_id and shift_date between requested_start and requested_end and status<>'cancelled';select coalesce(jsonb_agg(to_jsonb(w) order by w.starts_at),'[]'::jsonb) into snap from public.work_shifts w where w.store_id=requested_establishment_id and w.shift_date between requested_start and requested_end and w.publication_status='published';insert into public.schedule_publications(organization_id,store_id,period_start,period_end,version,snapshot,published_by) values(org,requested_establishment_id,requested_start,requested_end,v,snap,auth.uid());insert into public.workforce_notifications(organization_id,employee_id,kind,title,body) select distinct org,employee_id,'schedule_published','Escala publicada','Sua escala foi publicada ou atualizada.' from public.work_shifts where store_id=requested_establishment_id and shift_date between requested_start and requested_end;perform private.workforce_audit(org,requested_establishment_id,'schedule_published','schedule_publication',null,null,jsonb_build_object('version',v,'start',requested_start,'end',requested_end));return jsonb_build_object('version',v,'shifts',snap);end$$;
create or replace function public.workforce_copy_previous_week_preview(requested_establishment_id uuid,requested_week_start date) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;payload jsonb;pid uuid;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.workforce_can_access(org,requested_establishment_id,'create_shift') then raise exception 'Sem permissão';end if;select coalesce(jsonb_agg(jsonb_build_object('employee_id',employee_id,'starts_at',starts_at+interval '7 days','ends_at',ends_at+interval '7 days','break_minutes',break_minutes,'role_context',role_context) order by starts_at),'[]'::jsonb) into payload from public.work_shifts where store_id=requested_establishment_id and shift_date between requested_week_start-7 and requested_week_start-1 and status<>'cancelled';insert into public.workforce_action_previews(organization_id,store_id,requested_by,action_type,payload) values(org,requested_establishment_id,auth.uid(),'copy_previous_week',payload) returning id into pid;return jsonb_build_object('preview_id',pid,'items',payload,'requires_confirmation',true);end$$;
create or replace function public.workforce_record_clock(requested_establishment_id uuid,requested_type text,requested_source text default 'pwa',requested_device_id text default null) returns public.time_clock_entries language plpgsql security definer set search_path=public,private,pg_temp as $$declare employee public.custom_staff_members;org uuid;entry public.time_clock_entries;current_shift uuid;last_type text;begin select m.* into employee from public.custom_staff_members m where m.user_id=auth.uid() and m.status='active' order by m.created_at limit 1;if employee.id is null then raise exception 'Funcionário não encontrado';end if;select organization_id into org from public.establishments where id=requested_establishment_id;if employee.organization_id<>org or not exists(select 1 from public.employee_store_assignments a where a.employee_id=employee.id and a.store_id=requested_establishment_id and a.starts_on<=current_date and (a.ends_on is null or a.ends_on>=current_date)) and employee.primary_store_id<>requested_establishment_id then raise exception 'Funcionário sem acesso à unidade';end if;select entry_type into last_type from public.time_clock_entries where employee_id=employee.id order by occurred_at desc limit 1;if (requested_type='clock_in' and last_type in('clock_in','break_start','break_end')) or (requested_type='break_start' and last_type not in('clock_in','break_end')) or (requested_type='break_end' and last_type<>'break_start') or (requested_type='clock_out' and last_type not in('clock_in','break_end')) then raise exception 'Sequência de ponto inválida';end if;select id into current_shift from public.work_shifts where employee_id=employee.id and status<>'cancelled' and now() between starts_at-interval '4 hours' and ends_at+interval '4 hours' order by starts_at limit 1;insert into public.time_clock_entries(organization_id,store_id,employee_id,shift_id,entry_type,occurred_at,source,device_id,created_by) values(org,requested_establishment_id,employee.id,current_shift,requested_type,clock_timestamp(),requested_source,nullif(requested_device_id,''),auth.uid()) returning * into entry;if current_shift is not null then update public.work_shifts set status=case when requested_type='clock_in' then 'in_progress' when requested_type='clock_out' then 'completed' else status end,updated_at=now() where id=current_shift;end if;insert into public.support_agent_presence(organization_id,store_id,user_id,status,last_seen_at,updated_at) values(org,requested_establishment_id,auth.uid(),case when requested_type='break_start' then 'paused' when requested_type='clock_out' then 'offline' else 'available' end,now(),now()) on conflict(organization_id,user_id) do update set store_id=excluded.store_id,status=excluded.status,last_seen_at=now(),updated_at=now();perform private.workforce_audit(org,requested_establishment_id,requested_type,'time_clock_entry',entry.id,null,to_jsonb(entry));return entry;end$$;
create or replace function public.workforce_request_clock_correction(requested_entry_id uuid,requested_type text,requested_at timestamptz,requested_reason text) returns public.time_clock_correction_requests language plpgsql security definer set search_path=public,private,pg_temp as $$declare e public.time_clock_entries;r public.time_clock_correction_requests;begin select * into e from public.time_clock_entries where id=requested_entry_id;if not private.workforce_employee_self(e.employee_id) then raise exception 'Sem acesso ao ponto';end if;insert into public.time_clock_correction_requests(organization_id,employee_id,entry_id,requested_type,requested_at,reason,previous_value,new_value,requested_by) values(e.organization_id,e.employee_id,e.id,requested_type,requested_at,btrim(requested_reason),to_jsonb(e),jsonb_build_object('entry_type',requested_type,'occurred_at',requested_at),auth.uid()) returning * into r;insert into public.workforce_approval_requests(organization_id,store_id,employee_id,request_type,target_id,payload,requested_by) values(e.organization_id,e.store_id,e.employee_id,'clock_correction',r.id,to_jsonb(r),auth.uid());perform private.workforce_audit(e.organization_id,e.store_id,'clock_correction_requested','time_clock_correction',r.id,to_jsonb(e),to_jsonb(r));return r;end$$;
create or replace function public.workforce_decide_clock_correction(requested_correction_id uuid,requested_approve boolean,requested_reason text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare r public.time_clock_correction_requests;e public.time_clock_entries;begin select * into r from public.time_clock_correction_requests where id=requested_correction_id for update;select * into e from public.time_clock_entries where id=r.entry_id;if not private.workforce_can_access(r.organization_id,e.store_id,'correct_clock') then raise exception 'Sem permissão';end if;update public.time_clock_correction_requests set status=case when requested_approve then 'approved' else 'rejected' end,decided_by=auth.uid(),decided_at=now() where id=r.id;if requested_approve then update public.time_clock_entries set entry_type=r.requested_type,occurred_at=r.requested_at,source='supervisor_correction',metadata=metadata||jsonb_build_object('correction_id',r.id,'reason',r.reason) where id=e.id;end if;update public.workforce_approval_requests set status=case when requested_approve then 'approved' else 'rejected' end,decided_by=auth.uid(),decided_at=now(),decision_reason=requested_reason where target_id=r.id and request_type='clock_correction';perform private.workforce_audit(r.organization_id,e.store_id,case when requested_approve then 'clock_correction_approved' else 'clock_correction_rejected' end,'time_clock_entry',e.id,to_jsonb(e),(select to_jsonb(x) from public.time_clock_entries x where x.id=e.id));return jsonb_build_object('approved',requested_approve);end$$;

create or replace function public.workforce_phase18_summary(requested_establishment_id uuid,requested_start date default current_date,requested_end date default current_date,requested_all_units boolean default false) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$
declare org uuid; result jsonb;
begin
 select organization_id into org from public.establishments where id=requested_establishment_id;
 if not private.workforce_can_access(org,case when requested_all_units then null else requested_establishment_id end,'view') then raise exception 'Sem acesso à gestão de pessoas'; end if;
 with scoped_stores as(
  select id,name from public.establishments where organization_id=org and (requested_all_units or id=requested_establishment_id)
 ), shift_data as(
  select w.*,m.name,m.hourly_cost_cents,m.monthly_cost_cents,r.name role_name,s.name store_name,
   coalesce((select min(t.occurred_at) from public.time_clock_entries t where t.shift_id=w.id and t.entry_type='clock_in'),w.starts_at) actual_start,
   coalesce((select max(t.occurred_at) from public.time_clock_entries t where t.shift_id=w.id and t.entry_type='clock_out'),least(now(),w.ends_at)) actual_end
  from public.work_shifts w join scoped_stores s on s.id=w.store_id join public.custom_staff_members m on m.id=w.employee_id join public.staff_roles r on r.id=m.role_id
  where w.shift_date between requested_start and requested_end
 ), worked as(
  select sd.*,greatest(0,(extract(epoch from(actual_end-actual_start))/60-break_minutes)::integer) worked_minutes from shift_data sd
 )
 select jsonb_build_object(
  'cards',jsonb_build_object(
   'active_employees',(select count(*) from public.custom_staff_members m where m.organization_id=org and m.status='active'),
   'on_shift',(select count(*) from shift_data where now() between starts_at and ends_at and status in('scheduled','confirmed','in_progress')),
   'late',(select count(*) from shift_data w where w.shift_date=current_date and now()>w.starts_at+make_interval(mins=>coalesce((select lateness_tolerance_minutes from public.workforce_settings where organization_id=org),10)) and not exists(select 1 from public.time_clock_entries t where t.shift_id=w.id and t.entry_type='clock_in')),
   'absent',(select count(*) from shift_data where status='absent'),
   'on_break',(select count(*) from public.time_clock_entries t join scoped_stores s on s.id=t.store_id where t.entry_type='break_start' and not exists(select 1 from public.time_clock_entries x where x.employee_id=t.employee_id and x.occurred_at>t.occurred_at and x.entry_type in('break_end','clock_out'))),
   'overtime_minutes',(select coalesce(sum(greatest(0,worked_minutes-(extract(epoch from(ends_at-starts_at))/60-break_minutes)::integer)),0) from worked),
   'labor_cost_cents',(select coalesce(sum(round(worked_minutes*coalesce(hourly_cost_cents,monthly_cost_cents/220.0,0)/60.0)),0) from worked)
  ),
  'current_staff',(select coalesce(jsonb_agg(jsonb_build_object('employee_id',employee_id,'name',name,'role',role_name,'store',store_name,'starts_at',starts_at,'ends_at',ends_at,'status',status) order by starts_at),'[]'::jsonb) from shift_data where now() between starts_at and ends_at),
  'day_schedule',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'employee_id',employee_id,'name',name,'role',role_name,'store',store_name,'starts_at',starts_at,'ends_at',ends_at,'status',status,'publication_status',publication_status) order by starts_at),'[]'::jsonb) from shift_data),
  'coverage',(select coalesce(jsonb_agg(row_data),'[]'::jsonb) from(select jsonb_build_object('store_id',store_id,'store',store_name,'hour',extract(hour from starts_at)::integer,'staff',count(*),'level',case when count(*)<2 then 'low' when count(*)<4 then 'adequate' else 'high' end) row_data from shift_data group by store_id,store_name,extract(hour from starts_at)) c),
  'productivity',jsonb_build_object(
   'support',(select count(*) from public.support_assignment_history h join scoped_stores s on s.id=h.establishment_id where h.accepted_at::date between requested_start and requested_end),
   'kitchen',(select count(*) from public.kitchen_tickets k join scoped_stores s on s.id=k.establishment_id where k.delivered_at::date between requested_start and requested_end),
   'delivery',(select count(*) from public.deliveries d join scoped_stores s on s.id=d.establishment_id where d.delivered_at::date between requested_start and requested_end),
   'cashier',(select count(*) from public.pos_sales p join scoped_stores s on s.id=p.establishment_id where p.created_at::date between requested_start and requested_end and p.status<>'voided')
  ),
  'alerts',(select coalesce(jsonb_agg(row_data),'[]'::jsonb) from(select jsonb_build_object('kind','coverage','message',store_name||' tem cobertura baixa no horário de '||extract(hour from starts_at)::integer||'h.') row_data from shift_data group by store_name,extract(hour from starts_at) having count(*)<2 limit 8) a),
  'managerial_notice','Custos e horas extras são estimativas gerenciais, não folha oficial nem interpretação jurídica.'
 ) into result;
 return result;
end$$;

grant execute on function public.workforce_save_shift(uuid,uuid,uuid,timestamptz,timestamptz,integer,text),public.workforce_publish_schedule(uuid,date,date),public.workforce_copy_previous_week_preview(uuid,date),public.workforce_record_clock(uuid,text,text,text),public.workforce_request_clock_correction(uuid,text,timestamptz,text),public.workforce_decide_clock_correction(uuid,boolean,text),public.workforce_phase18_summary(uuid,date,date,boolean) to authenticated;
revoke all on function public.workforce_save_shift(uuid,uuid,uuid,timestamptz,timestamptz,integer,text),public.workforce_publish_schedule(uuid,date,date),public.workforce_copy_previous_week_preview(uuid,date),public.workforce_record_clock(uuid,text,text,text),public.workforce_request_clock_correction(uuid,text,timestamptz,text),public.workforce_decide_clock_correction(uuid,boolean,text),public.workforce_phase18_summary(uuid,date,date,boolean) from public,anon;

insert into public.workforce_settings(organization_id) select id from public.organizations on conflict do nothing;
insert into public.employee_store_assignments(organization_id,employee_id,store_id,starts_on,temporary)
select e.organization_id,m.id,m.establishment_id,coalesce(m.hire_date,m.created_at::date),false from public.custom_staff_members m join public.establishments e on e.id=m.establishment_id on conflict do nothing;
